INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_LYDIAN','Lydian Kingdom (Iron Age western Anatolia)',-1200,-540)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_MUNN_MOTHER_GODS','secondary scholarship','Munn, Mark. The Mother of the Gods, Athens, and the Tyranny of Asia: A Study of Sovereignty in Ancient Religion (University of California Press, 2006)','Lydian and Anatolian sovereignty religion; Kuvava/Kybebe, Santas, and the transmission of the Mother of the Gods into Greek and Roman cult.')
INSERT INTO _e VALUES
 ('ENT_LYD_PANTHEON','Lydian Pantheon','collective','collective','Lydian','civic polytheism','B','Collective hub for the deities of the Iron Age Lydian kingdom (Sardis, c. 1200-540 BCE), attested in Lydian-language inscriptions, theophoric names, and Greek sources (Herodotus, Hipponax). Munn (2006).'),
 ('ENT_LYD_KUVAVA','Kuvava (Kybebe)','deity','deity','Lydian','mother goddess, sovereignty, mountains','B','The Lydian mother-goddess, attested in Lydian inscriptions as Kuvava and in Greek as Kybebe (Herodotus 5.102; Hipponax names her at Sardis). Descended from the Luwian/Neo-Hittite Kubaba of Carchemish and ancestral to the Phrygian/Greek Cybele; central to Munn''s account of Anatolian divine sovereignty. Distinct local form, not the Phrygian Matar.'),
 ('ENT_LYD_SANTAS','Santas (Sandon)','deity','deity','Lydian','war, plague, kingship, club-bearing hero-god','B','Lydian war- and plague-god, the Anatolian Sandon/Sandas figure interpreted by Greeks as a Heracles. Munn connects him to Lydian dynastic ancestry (the Tylonid/Heraclid line at Sardis); continuous with the Luwian Santa and Cilician Sandas. Attested via theophoric onomastics and the Greek Herakles-equation.'),
 ('ENT_LYD_ARTIMUS','Artimus','deity','deity','Lydian','wild nature, protection, the dead','B','Lydian goddess attested in Lydian inscriptions (frequently paired with Pldans), regularly equated with Greek Artemis; her cult is prominent at Sardis and Ephesus'' Anatolian background. Munn (2006); Lydian epigraphic corpus.'),
 ('ENT_LYD_PLDANS','Pldans','deity','deity','Lydian','divine guardianship, oracular/solar associations','C','Lydian god named in inscriptions (paired with Artimus in protective formulae), conventionally identified with Greek Apollo on phonetic and functional grounds. Attestation is epigraphic and partly conjectural. Munn (2006).'),
 ('ENT_LYD_LAMETRUS','Lametrus','deity','deity','Lydian','grain, fertility, earth','C','Lydian goddess attested in inscriptions, identified with Greek Demeter through both name and agrarian function. Reflects the shared Anatolian-Greek grain-mother substrate. Munn (2006); Lydian epigraphy.'),
 ('ENT_LYD_BAKIVALIS','Bakivalis','deity','deity','Lydian','wine, ecstatic cult, vegetation','C','Lydian theonym/theophoric element (Baki-) reflecting a Dionysus-type wine and ecstatic-cult deity; the Lydian-Phrygian Bakkhos sphere from which the Greek epithet Bakchos is partly drawn. Attestation chiefly onomastic. Munn (2006).'),
 ('ENT_LYD_KANDAULES','Kandaules','deity','deity','Lydian','dog-throttling, gateways, chthonic protection','C','Lydian divine epithet ''Kandaules'' (the ''dog-throttler''), reported by Hipponax as a Lydian title of Hermes; also the throne-name of the last Heraclid king of Sardis (Herodotus 1.7ff). A Hermes-type guardian/psychopomp figure. Munn (2006).');
